def compute(vars):
    current = vars["v1"]
    prior = vars["v2"]
    if prior == 0:
        return None
    change = current - prior
    percentage_change = change / prior * 100
    return {
        "value": percentage_change,
        "trace": {
            "current_connections_2018": current,
            "prior_connections_2017": prior,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
